void far GRectInvOutline(struct Rect far *rect, int thick)
{
    int x1;
    int y1;
    int x2;
    int y2;
    struct Rect far *p;

    p = rect;
    if (p == 0)
        return;
    x1 = p->left;
    y1 = p->top;
    x2 = p->right;
    y2 = p->bottom;
    if (thick != 0) {
        GInvBox(thick + x1, thick + y1 - 1, x2 - thick - 1, y1);
        GInvBox(thick + x1, y2 - thick, x2 - thick - 1, y2 - 1);
        GInvBox(thick + x1 - 1, y1, x1, y2 - 1);
        GInvBox(x2 - 1, y1, x2 - thick, y2 - 1);
    }
}
